// ListFirewallRulesAll returns an iterator over every result of ListFirewallRules, reading
// page after page. params.Page is the first page (0 by default) and
// params.PageSize the page size (100 by default).
func (s *FirewallService) ListFirewallRulesAll(ctx context.Context, rulesetID string, params *ListFirewallRulesParams) iter.Seq2[FirewallRuleResource, error] {
	return func(yield func(FirewallRuleResource, error) bool) {
		var p ListFirewallRulesParams
		if params != nil {
			p = *params
		}
		if p.PageSize <= 0 {
			p.PageSize = defaultPageSize
		}
		seen := 0
		for {
			page, err := s.ListFirewallRules(ctx, rulesetID, &p)
			if err != nil {
				var zero FirewallRuleResource
				yield(zero, err)
				return
			}
			for _, item := range page.Rules {
				if !yield(item, nil) {
					return
				}
			}
			seen += len(page.Rules)
			if len(page.Rules) < int(p.PageSize) || (page.TotalCount > 0 && seen >= int(page.TotalCount)) {
				return
			}
			p.Page++
		}
	}
}

